import { readFile, writeFile } from 'node:fs/promises';

import { format } from 'prettier';

// Keep every existing script/weight, but modern Tauri WebViews only need WOFF2.
let css =
  '/* Generated by scripts/prepare-font-assets.mjs. Keeps all installed 400-normal subsets. */\n';
for (const family of ['fira-code', 'jetbrains-mono']) {
  const source = await readFile(
    new URL(`../node_modules/@fontsource/${family}/index.css`, import.meta.url),
    'utf8',
  );
  css += source.replace(
    /src:\s*url\(\.\/files\/([^)]*\.woff2)\)[^;]+;/g,
    (_, file) => `src: url('@fontsource/${family}/files/${file}') format('woff2');`,
  );
}
for (const family of ['PureNerdFont', 'Pure Nerd Font']) {
  css += `\n@font-face { font-family: '${family}'; font-display: swap; src: url('@azurity/pure-nerd-font/PureNerdFont.woff2') format('woff2'); }\n`;
}
const output = await format(css, { parser: 'css', singleQuote: true, printWidth: 100 });
const file = new URL('../src/generated/mono-fonts.css', import.meta.url);
let previous;
try {
  previous = await readFile(file, 'utf8');
} catch {
  /* First generation. */
}
if (previous !== output) {
  if (process.argv.includes('--check'))
    throw new Error('Generated font faces are stale. Run node scripts/prepare-font-assets.mjs.');
  await writeFile(file, output);
}

// KaTeX also ships every face in three formats; preserve the WOFF2 faces and all styling.
const katexSource = await readFile(
  new URL('../node_modules/katex/dist/katex.min.css', import.meta.url),
  'utf8',
);
const katexCss = katexSource.replace(
  /src:url\(fonts\/([^)]+\.woff2)\)[^;}]+/g,
  (_, file) => `src:url('katex/dist/fonts/${file}') format('woff2')`,
);
const katexOutput = await format(
  '/* Generated by scripts/prepare-font-assets.mjs. */\n' + katexCss,
  { parser: 'css', singleQuote: true, printWidth: 100 },
);
const katexFile = new URL('../src/generated/katex.css', import.meta.url);
let previousKatex;
try {
  previousKatex = await readFile(katexFile, 'utf8');
} catch {
  /* First generation. */
}
if (previousKatex !== katexOutput) {
  if (process.argv.includes('--check'))
    throw new Error('Generated KaTeX faces are stale. Run node scripts/prepare-font-assets.mjs.');
  await writeFile(katexFile, katexOutput);
}
